ALTER TABLE exercises ADD COLUMN recommended_rest_seconds integer
    CHECK (recommended_rest_seconds BETWEEN 0 AND 3600);

-- RuFit editable starting values, not imported GymWork recommendations.
-- Rationale and source: docs/exercise-rest.md.
UPDATE exercises SET recommended_rest_seconds = CASE
    WHEN id IN ('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003',
                '00000000-0000-4000-8000-000000000013') THEN 180
    WHEN id IN ('00000000-0000-4000-8000-000000000009','00000000-0000-4000-8000-000000000010',
                '00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000018') THEN 90
    ELSE 120 END
WHERE owner_name IS NULL AND id IN (
    '00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002',
    '00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000004',
    '00000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000006',
    '00000000-0000-4000-8000-000000000007','00000000-0000-4000-8000-000000000008',
    '00000000-0000-4000-8000-000000000009','00000000-0000-4000-8000-000000000010',
    '00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000012',
    '00000000-0000-4000-8000-000000000013','00000000-0000-4000-8000-000000000014',
    '00000000-0000-4000-8000-000000000015','00000000-0000-4000-8000-000000000016',
    '00000000-0000-4000-8000-000000000017','00000000-0000-4000-8000-000000000018');

CREATE TABLE exercise_rest_preferences (
    owner_name varchar(100) NOT NULL,
    exercise_id uuid NOT NULL REFERENCES exercises(id),
    rest_seconds integer CHECK (rest_seconds BETWEEN 0 AND 3600),
    version bigint NOT NULL CHECK (version > 0),
    PRIMARY KEY (owner_name, exercise_id)
);
